mapper.select:
select
from first_mile_weight_allocation where is_deleted = false
and source_id in
#{item}
and cost_allocation_status in
#{item}

select wa.id, wa.source_id, wa.source_code sourceCode, wa.delivery_detail_id, wa.business_code businessCode, wa.transport_no transportNo, wa.product_name productName, wa.cost_allocation_status costAllocationStatus, wa.sku_id, wa.sku_no skuNo, wa.platform_sku_no platformSkuNo, wa.box_id, wa.box_no boxNo, wa.delivery_qty deliveryQty, wa.box_length, wa.box_width, wa.box_height, wa.box_size_unit, wa.out_stock_weight outStockWeight, wa.charged_weight chargedWeight, wa.volume_weight, wa.product_weight productWeight, wa.allocation_weight allocationWeight, wa.weight_unit, wa.supplier_id, wa.supplier_name supplierName, wa.allocation_type allocationType, wa.fee_rule feeRule, wa.shop_id, wa.shop_name shopName, wa.to_country toCountry, wa.from_warehouse_id fromWarehouseId, wa.calculate_period_id, wa.calculate_month, wa.logistics_bill_id from first_mile_weight_allocation wa
wa.id in
#{id}
ORDER BY
${item.field} ${item.sort}
wa.id DESC
